// src/services/api.js

// Base URL for all API calls (configurable via .env)

//const BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8080';
const BASE_URL = '';


// Core request helper
async function request(path, options = {}) {
  const response = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...options.headers },
    ...options,
  });

  if (!response.ok) {
    let errorText = `Request failed: ${response.status}`;
    try {
      const errorData = await response.json();
      errorText = errorData.message || errorText;
    } catch {
      // ignore JSON parse errors
    }
    throw new Error(errorText);
  }

  return response.json();
}

// Questions
export function getQuestions() {
  return request('/questions');
}

export function getQuestionById(id) {
  return request(`/questions/${id}`);
}

// Answers
export function getAnswersByQuestionId(id) {
  return request(`/answers/question/${id}`);
}

export function postAnswer(questionId, answer) {
  return request(`/questions/${questionId}/answers`, {
    method: 'POST',
    body: JSON.stringify(answer),
  });
}

// Posting new questions
export function postQuestion(question) {
  return request('/questions', {
    method: 'POST',
    body: JSON.stringify(question),
  });
}

// Authentication (example)
export function login(credentials) {
  return request('/auth/login', {
    method: 'POST',
    body: JSON.stringify(credentials),
  });
}

export function register(data) {
  return request('/auth/register', {
    method: 'POST',
    body: JSON.stringify(data),
  });
}
